    private void btn_CrearActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btn_CrearActionPerformed

    try {
         int n = Integer.parseInt(txt_Numero.getText());

        if (n < 3 || n > 11 || n % 2 == 0) {
            JOptionPane.showMessageDialog(this, "Debe ingresar un número IMPAR entre 3 y 11");
            return;
            //Para que se vuelva a escribir
        }

        int[][] cuadro = new int[n][n];
        int numero = 1;
        int fila = 0;
        int columna = n / 2;

        while (numero <= n * n) {
            //para que valla de 1 a nxn
            cuadro[fila][columna] = numero++;
            //aumentador
            int nuevaFila = (fila - 1 + n) % n;
            int nuevaColumna = (columna + 1) % n;
            //los cambios de filas y columnas

            if (cuadro[nuevaFila][nuevaColumna] != 0) {
                fila = (fila + 1) % n;
                //Cambiar de fila
            } else {
                fila = nuevaFila;
                columna = nuevaColumna;
            }
        }

        // Mostrar cuadro en el JTextArea
        StringBuilder objString = new StringBuilder();
        //cadernas de string 
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                objString.append(String.format("%10d", cuadro[i][j]));
            }
           objString.append("\n\n");
           //separador 
        }

        txt_Area_Resultado.setText(objString.toString());
        //Para que aparezca

    } catch (NumberFormatException e) {
        JOptionPane.showMessageDialog(this, "Ingrese un número válido.");
    }



        // TODO add your handling code here:
    }//GEN-LAST:event_btn_CrearActionPerformed

